import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import api from '../api/axios';
import { Container, Table, Spinner } from 'react-bootstrap';

const Schedule = () => {
  const [schedule, setSchedule] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const roles = useSelector(state => state.auth.roles || []);

  useEffect(() => {
    fetchSchedule();
  }, []);

  const fetchSchedule = async () => {
    setLoading(true);
    try {
      const res = await api.get('/schedule');
      setSchedule(res.data);
    } catch (err) {
      setError(err.response?.data?.error || 'Ошибка загрузки расписания');
    } finally {
      setLoading(false);
    }
  };

  const isDirector = roles.includes('Директор');

  if (loading) {
    return (
      <Container className="text-center mt-5">
        <Spinner animation="border" variant="primary" />
        <p>Загрузка расписания...</p>
      </Container>
    );
  }

  if (error) {
    return (
      <Container className="mt-4">
        <h3>Расписание</h3>
        <div className="alert alert-danger">{error}</div>
      </Container>
    );
  }

  return (
    <Container className="mt-4">
      <h3 style={{ textAlign: 'center' }}>Расписание на {new Date().toLocaleDateString('ru-RU', { month: 'long', year: 'numeric' })}</h3>
      {schedule.length === 0 ? (
        <div className="alert alert-info">Нет уроков в расписании</div>
      ) : (
        <Table striped bordered hover>
          <thead>
            <tr>
              <th>№</th>
              <th>День недели</th>
              <th>Дата</th>
              <th>Предмет</th>
              <th>Учитель</th>
              <th>Домашнее задание</th>
              <th>Оценка</th>
            </tr>
          </thead>
          <tbody>
            {schedule.map(item => (
              <tr key={item.id}>
                <td>{item.lesson_number}</td>
                <td>{item.day_of_week}</td>
                <td>{new Date(item.date).toLocaleDateString('ru-RU')}</td>
                <td>{item.subject_name}</td>
                <td>{item.teacher_name}</td>
                <td>{item.homework || '—'}</td>
                <td>{item.grade || '—'}</td>
              </tr>
            ))}
          </tbody>
        </Table>
      )}
      
      {isDirector && (
        <div className="mt-3">
          <p className="text-muted">
            <em>Как директор, вы можете добавлять уроки через админ-панель</em>
          </p>
        </div>
      )}
    </Container>
  );
};

export default Schedule;
